/** inspired by x.ai */

import FeatureSectionV7 from "./components/feature-section-v7"

export default function Page() {
  return <FeatureSectionV7 />
}

@keyframes fsv7-illus-draw {
  to {
    stroke-dashoffset: 0;
  }
}

@keyframes fsv7-illus-fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes fsv7-illus-scale-in {
  from {
    opacity: 0;
    transform: scale(0.88);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

@keyframes fsv7-illus-slide-in {
  from {
    opacity: 0;
    transform: translateX(6px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

.fsv7-planner-frame,
.fsv7-planner-nav,
.fsv7-planner-tile {
  opacity: 0;
  transform-box: fill-box;
  transform-origin: center;
}

.fsv7-planner-chart--active .fsv7-planner-frame {
  animation: fsv7-illus-scale-in 520ms cubic-bezier(0.22, 1, 0.36, 1) 80ms forwards;
}

.fsv7-planner-chart--active .fsv7-planner-nav--1 {
  animation: fsv7-illus-fade-in 320ms ease-out 400ms forwards;
}

.fsv7-planner-chart--active .fsv7-planner-nav--2 {
  animation: fsv7-illus-fade-in 320ms ease-out 480ms forwards;
}

.fsv7-planner-chart--active .fsv7-planner-nav--3 {
  animation: fsv7-illus-fade-in 320ms ease-out 560ms forwards;
}

.fsv7-planner-chart--active .fsv7-planner-tile--1 {
  animation: fsv7-illus-scale-in 480ms cubic-bezier(0.22, 1, 0.36, 1) 640ms forwards;
}

.fsv7-planner-chart--active .fsv7-planner-tile--2 {
  animation: fsv7-illus-scale-in 480ms cubic-bezier(0.22, 1, 0.36, 1) 760ms forwards;
}

.fsv7-planner-chart--active .fsv7-planner-tile--3 {
  animation: fsv7-illus-scale-in 460ms cubic-bezier(0.22, 1, 0.36, 1) 860ms forwards;
}

.fsv7-planner-chart--active .fsv7-planner-tile--4 {
  animation: fsv7-illus-scale-in 460ms cubic-bezier(0.22, 1, 0.36, 1) 940ms forwards;
}

.fsv7-planner-chart--active .fsv7-planner-tile--5 {
  animation: fsv7-illus-scale-in 560ms cubic-bezier(0.16, 1, 0.3, 1) 1.02s forwards;
}

.fsv7-search-frame,
.fsv7-search-sidebar,
.fsv7-search-prompt,
.fsv7-search-output,
.fsv7-search-cursor {
  opacity: 0;
  transform-box: fill-box;
  transform-origin: center;
}

.fsv7-search-chart--active .fsv7-search-frame {
  animation: fsv7-illus-scale-in 520ms cubic-bezier(0.22, 1, 0.36, 1) 100ms forwards;
}

.fsv7-search-chart--active .fsv7-search-sidebar {
  animation: fsv7-illus-fade-in 360ms ease-out 420ms forwards;
}

.fsv7-search-chart--active .fsv7-search-prompt {
  animation: fsv7-illus-fade-in 400ms ease-out 520ms forwards;
}

.fsv7-search-chart--active .fsv7-search-output {
  animation: fsv7-illus-slide-in 440ms cubic-bezier(0.22, 1, 0.36, 1) 880ms forwards;
}

.fsv7-search-chart--active .fsv7-search-cursor {
  animation: fsv7-illus-fade-in 320ms ease-out 1.15s forwards;
}

.fsv7-guides-layer,
.fsv7-guides-thumb,
.fsv7-guides-doc,
.fsv7-guides-badge {
  opacity: 0;
  transform-box: fill-box;
  transform-origin: center;
}

.fsv7-guides-thumb__line {
  stroke-dasharray: 1;
  stroke-dashoffset: 1;
}

.fsv7-guides-chart--active .fsv7-guides-layer--3 {
  animation: fsv7-illus-scale-in 480ms cubic-bezier(0.22, 1, 0.36, 1) 200ms forwards;
}

.fsv7-guides-chart--active .fsv7-guides-layer--2 {
  animation: fsv7-illus-scale-in 500ms cubic-bezier(0.22, 1, 0.36, 1) 320ms forwards;
}

.fsv7-guides-chart--active .fsv7-guides-layer--1 {
  animation: fsv7-illus-scale-in 520ms cubic-bezier(0.16, 1, 0.3, 1) 440ms forwards;
}

.fsv7-guides-chart--active .fsv7-guides-thumb {
  animation: fsv7-illus-scale-in 480ms cubic-bezier(0.22, 1, 0.36, 1) 640ms forwards;
}

.fsv7-guides-chart--active .fsv7-guides-thumb__line {
  animation: fsv7-illus-draw 520ms cubic-bezier(0.16, 1, 0.3, 1) 760ms forwards;
}

.fsv7-guides-chart--active .fsv7-guides-doc {
  animation: fsv7-illus-scale-in 500ms cubic-bezier(0.16, 1, 0.3, 1) 880ms forwards;
}

.fsv7-guides-chart--active .fsv7-guides-badge {
  animation: fsv7-illus-scale-in 400ms cubic-bezier(0.34, 1.2, 0.64, 1) 960ms forwards;
}

@media (prefers-reduced-motion: reduce) {
  .fsv7-planner-frame,
  .fsv7-planner-nav,
  .fsv7-planner-tile,
  .fsv7-search-frame,
  .fsv7-search-sidebar,
  .fsv7-search-prompt,
  .fsv7-search-output,
  .fsv7-search-cursor,
  .fsv7-guides-layer,
  .fsv7-guides-thumb,
  .fsv7-guides-doc,
  .fsv7-guides-badge {
    opacity: 1;
    transform: none;
    animation: none;
  }

  .fsv7-guides-thumb__line {
    stroke-dashoffset: 0;
    animation: none;
  }
}

import type { ComponentType } from "react"

import { ArrowUpRightIcon } from "lucide-react"
import Link from "next/link"

import { cn } from "@/lib/utils"

import GuidesMemoriesIllustration from "./guides-memories-illustration"
import TripPlannerIllustration from "./trip-planner-illustration"
import { FeatureCardCorners } from "./feature-card-corners"
import SmartSearchIllustration from "./smart-search-illustration"
import { featureColumns, type FeatureIllustrationId } from "../lib/features"

const illustrationComponents: Record<FeatureIllustrationId, ComponentType> = {
  "trip-planner": TripPlannerIllustration,
  "smart-search": SmartSearchIllustration,
  "guides-memories": GuidesMemoriesIllustration,
}

export default function FeatureGrid() {
  return (
    <ul className="m-0 mt-6 grid list-none grid-cols-1 p-0 lg:mt-8 lg:grid-cols-3">
      {featureColumns.map(
        ({ id, title, description, ctaLabel, ctaHref, illustration }, index) => {
          const Illustration = illustrationComponents[illustration]

          return (
            <li
              key={id}
              className={cn(
                "group relative flex min-h-104 flex-col gap-6 border border-border px-6 py-12 sm:min-h-112 sm:px-8 sm:py-14 lg:min-h-120 lg:flex-col lg:gap-7 lg:px-10 lg:py-16",
                index > 0 && "-mt-px lg:mt-0 lg:-ml-px"
              )}
            >
              <FeatureCardCorners />

              <div>
                <h3 className="m-0 text-xl font-medium tracking-[-0.02em] text-foreground sm:text-[1.375rem]">
                  {title}
                </h3>
                <p className="m-0 mt-3 max-w-[36ch] text-[0.9375rem] leading-[1.65] text-muted-foreground">
                  {description}
                </p>
              </div>

              <div className="flex flex-1 flex-col">
                <div className="pointer-events-none flex w-full min-h-0 flex-1 items-end justify-center overflow-hidden">
                  <Illustration />
                </div>

                <div className="relative z-10 mt-auto flex justify-center pt-8">
                  <Link
                    href={ctaHref}
                    className="inline-flex items-center gap-1.5 rounded-full border border-border px-6 py-2.5 text-sm font-medium text-foreground transition-colors hover:border-foreground/30 hover:bg-muted"
                  >
                    {ctaLabel}
                    <ArrowUpRightIcon
                      className="size-3.5 shrink-0"
                      aria-hidden
                    />
                  </Link>
                </div>
              </div>
            </li>
          )
        }
      )}
    </ul>
  )
}

const cornerClassName =
  "pointer-events-none absolute z-10 size-1.5 bg-foreground"

export function FeatureCardCorners() {
  return (
    <>
      <span className={`${cornerClassName} top-0 left-0 -translate-x-1/2 -translate-y-1/2`} aria-hidden />
      <span
        className={`${cornerClassName} top-0 right-0 translate-x-1/2 -translate-y-1/2`}
        aria-hidden
      />
      <span
        className={`${cornerClassName} bottom-0 left-0 -translate-x-1/2 translate-y-1/2`}
        aria-hidden
      />
      <span
        className={`${cornerClassName} bottom-0 right-0 translate-x-1/2 translate-y-1/2`}
        aria-hidden
      />
    </>
  )
}

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"

type FeatureIllustrationProps = {
  viewBox: string
  children: ReactNode
  className?: string
  svgClassName?: string
}

export function FeatureIllustration({
  viewBox,
  children,
  className,
  svgClassName,
}: FeatureIllustrationProps) {
  return (
    <div
      className={cn(
        "flex size-full min-h-0 items-center justify-center opacity-40 motion-safe:transition-opacity duration-200 ease-out group-hover:opacity-70",
        className
      )}
    >
      <svg
        aria-hidden
        viewBox={viewBox}
        preserveAspectRatio="xMidYMid meet"
        className={cn("h-full w-full max-h-full max-w-full text-foreground", svgClassName)}
        fill="none"
        xmlns="http://www.w3.org/2000/svg"
      >
        {children}
      </svg>
    </div>
  )
}

import type { ReactNode, Ref } from "react"

import { cn } from "@/lib/utils"

export const illustrationSlotClassName =
  "mx-auto flex w-full min-h-0 aspect-[440/326] max-w-[22rem] sm:max-w-[25rem] lg:max-w-full"

type IllustrationSlotProps = {
  children: ReactNode
  className?: string
  ref?: Ref<HTMLDivElement>
}

export function IllustrationSlot({ children, className, ref }: IllustrationSlotProps) {
  return (
    <div ref={ref} className={cn(illustrationSlotClassName, className)}>
      {children}
    </div>
  )
}

"use client"

import { useEffect, useRef, useState } from "react"

export function useInViewOnce(threshold = 0.35) {
  const ref = useRef<HTMLDivElement>(null)
  const [active, setActive] = useState(false)

  useEffect(() => {
    const el = ref.current
    if (!el || active) return

    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry?.isIntersecting) {
          setActive(true)
          observer.disconnect()
        }
      },
      { threshold }
    )

    observer.observe(el)
    return () => observer.disconnect()
  }, [active, threshold])

  return { ref, active }
}
